input.sparql:
SELECT ?id ?class ?uri WHERE {
  ?z a ref:Zone ; 
     brick:hasPrimaryAttribute ?attr .
  FILTER regex(STR(?attr), "top_ZN") 
}

SELECT ?p ?tsid WHERE {
  ?p ref:hasTimeseriesId ?tsid .
  ?p brick:isTypeOf* brick:OccupancySensor .
  ?p brick:hasPrimaryProperty ?zone .
  FILTER regex(STR(?p), "Perimeter_top_ZN")
}

SELECT ?z ?name WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z rdfs:label ?name }
}
